fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    // If the array is empty, return two empty arrays
    if len == 0 {
        return (Vec::new(), Vec::new());
    }
    
    // If the array has one element, return one empty array and the array with that element
    if len == 1 {
        return (Vec::new(), a);
    }
    
    // Calculate the split index
    let mid = len / 2;
    
    // Split the array into two parts
    let first_half = a[0..mid].to_vec();
    let second_half = a[mid..].to_vec();
    
    (first_half, second_half)
}